f[1:])\n    phi = np.sum(x * y) / np.sum(x * x)\nelse:\n    phi = 0.5\n    \nprint(f\"AR(1) coefficient phi: {phi:.4f}\")\n\n# For differencing, the forecast is:\n# y(t+1) = phi * (y(t) - y(t-1)) + ... but wait, on differenced data\n# The model is: (1-B)Y(t) = phi*(1-B)Y(t-1) + e(t)\n# Which is: Y(t) - Y(t-1) = phi*(Y(t-1) - Y(t-2)) + e(t)\n# So the next first difference = phi * last first difference\n# Then forecast level = last level + forecast diff\n\n# Last observed level (1982):\nlast_level = data[-1]  # 64270 for 1982\n\n# Last first diff:\nlast_diff = diff[-1]  # 64270 - 64855 = -585\n\n# Forecast differenced value:\nforecast_diff = phi * last_diff\n\n# Forecast 1983 level:\nforecast_1983 = last_level + forecast_diff\n\nprint(f\"Last diff: {last_diff}\")\nprint(f\"Forecast diff: {forecast_diff:.2f}\")\nprint(f\"Forecast for 1983: {forecast_1983:.0f}\")\n\n# Round to nearest whole number\nforecast_rounded = round(forecast_1983)\nprint(f\"Rounded forecast: {forecast_rounded}\")\nEOF"}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
